import{_ as t,o,c as a,ag as s}from"./chunks/framework.By9v0nLp.js";const g=JSON.parse('{"title":"Text Tags","description":"","frontmatter":{},"headers":[],"relativePath":"guide/text-tags.md","filePath":"guide/text-tags.md"}'),d={name:"guide/text-tags.md"};function i(n,e,c,r,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="text-tags" tabindex="-1">Text Tags <a class="header-anchor" href="#text-tags" aria-label="Permalink to &quot;Text Tags&quot;">​</a></h1><p>Tags inside a line change how it types out: pauses, speed, colors, sounds, effects and portrait changes. They work in every line, including translated ones.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lines&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Fire?{pause:15} {speed:0.5}Very well.{speed:1} {shake}Respect it.{/shake}&quot;</span></span></code></pre></div><h2 id="all-tags" tabindex="-1">All tags <a class="header-anchor" href="#all-tags" aria-label="Permalink to &quot;All tags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tag</th><th>Effect</th></tr></thead><tbody><tr><td><code>{player}</code></td><td>The player&#39;s name</td></tr><tr><td><code>{pause:20}</code></td><td>Wait 20 ticks (1 second) before typing on</td></tr><tr><td><code>{speed:0.5}</code></td><td>Type at half speed from here. <code>{speed:2}</code> is twice as fast, <code>{speed:1}</code> is normal again</td></tr><tr><td><code>{emotion:sad}</code></td><td>Switch the portrait to <code>sad</code> at this point</td></tr><tr><td><code>{sound:minecraft:block.bell.use}</code></td><td>Play a sound at this point</td></tr><tr><td><code>{sound:minecraft:block.bell.use:1.5}</code></td><td>Play a sound with a pitch</td></tr><tr><td><code>{color:gold}</code> … <code>{/color}</code></td><td>Color the text between. A color name or a hex code like <code>{color:#ff8800}</code></td></tr><tr><td><code>{shake}</code> … <code>{/shake}</code></td><td>Trembling letters</td></tr><tr><td><code>{wave}</code> … <code>{/wave}</code></td><td>Wavy letters</td></tr><tr><td><code>{{</code></td><td>A plain <code>{</code></td></tr><tr><td><code>\\n</code></td><td>Start a new row</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><p><strong>Pauses and speed.</strong> <code>{pause}</code> and <code>{speed}</code> change timing only. Typing also pauses briefly on its own after <code>.</code> <code>!</code> <code>?</code> and <code>,</code> <code>;</code> <code>:</code> when more text follows. Players can change those pauses in their <a href="/wiki/nostalgicdialog/for-players#your-own-settings">settings</a>.</p><div class="tip custom-block"><p class="custom-block-title">Reset the speed</p><p>A <code>{speed:x}</code> tag stays in effect until another speed tag changes it, even into the next box. Close every slow or fast part with <code>{speed:1}</code>.</p></div><p><strong>Emotions.</strong> <code>{emotion:x}</code> switches the portrait when the typing reaches it, and the new face stays for the rest of the node. A node&#39;s <code>&quot;emotion&quot;</code> field sets the face it starts with.</p><p><strong>Sounds.</strong> Any sound event works: the game&#39;s, a mod&#39;s or one from your resource pack. Sound ids have a colon in them, so a pitch is a third part: <code>{sound:minecraft:entity.generic.eat:1.2}</code>.</p><p><strong>Colors.</strong> Color names are Minecraft&#39;s: <code>black</code>, <code>dark_blue</code>, <code>dark_green</code>, <code>dark_aqua</code>, <code>dark_red</code>, <code>dark_purple</code>, <code>gold</code>, <code>gray</code>, <code>dark_gray</code>, <code>blue</code>, <code>green</code>, <code>aqua</code>, <code>red</code>, <code>light_purple</code>, <code>yellow</code>, <code>white</code>. Colors can be nested.</p><p><strong>Skipping.</strong> When the player skips ahead with X or Shift, pauses are skipped and sounds that haven&#39;t played yet stay silent. Emotion changes still apply, so the face is always right.</p><p><strong>Typos.</strong> A tag the mod doesn&#39;t know is shown as written, such as <code>{shkae}</code>, so mistakes are easy to spot in game.</p><h2 id="line-breaks" tabindex="-1">Line breaks <a class="header-anchor" href="#line-breaks" aria-label="Permalink to &quot;Line breaks&quot;">​</a></h2><p>Lines wrap on their own, so you rarely need <code>\\n</code>. Use it when you want a row to end at an exact spot:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lines&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A riddle for you:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">What has roots nobody sees?&quot;</span></span></code></pre></div><p>Each entry in <code>lines</code> is already its own box, so to start a fresh box, start a new entry instead.</p>',17)])])}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
